CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 ANY COLLATE NOCASE, c1 INTEGER COLLATE NOCASE) STRICT;
INSERT OR IGNORE INTO t0(c0, c1) VALUES(x'762ec30a', -341);
INSERT OR IGNORE INTO t0(c0, c1) VALUES(-1, 639);
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 BLOB UNIQUE, c1 TEXT UNIQUE, c2 REAL, c3 TEXT, c4);
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, c4) VALUES(-448.2474, NULL, ' pad ', 318.584, NULL);
