SELECT length('omega'), upper('omega'), lower('omega'), substr('omega', 4, 4), instr('omega', '42'), replace('omega', 'é', ''), trim('omega'), ltrim('omega', 'ab'), hex('omega'), quote('omega'), unicode('omega'), 'omega' LIKE '%é%', 'omega' GLOB '?', char(83, 556), 'omega' || '42', 'omega' < '42', 'omega' = '42' COLLATE NOCASE;
SELECT length('日本'), upper('日本'), lower('日本'), substr('日本', -1, 1), instr('日本', 'alpha'), replace('日本', '', 'XY'), trim('日本'), ltrim('日本', 'ab'), hex('日本'), quote('日本'), unicode('日本'), '日本' LIKE '%a_', '日本' GLOB '*[a-m]*', char(81, 415), '日本' || 'alpha', '日本' < 'alpha', '日本' = 'alpha' COLLATE NOCASE;
SELECT length('zeta'), upper('zeta'), lower('zeta'), substr('zeta', 1, 5), instr('zeta', '0x1F'), replace('zeta', 'é', ''), trim('zeta'), ltrim('zeta', 'ab'), hex('zeta'), quote('zeta'), unicode('zeta'), 'zeta' LIKE '%a_', 'zeta' GLOB '*', char(76, 593), 'zeta' || '0x1F', 'zeta' < '0x1F', 'zeta' = '0x1F' COLLATE NOCASE;
SELECT length('psi'), upper('psi'), lower('psi'), substr('psi', 2, 4), instr('psi', 'it''s'), replace('psi', 'a', 'XY'), trim('psi'), ltrim('psi', 'ab'), hex('psi'), quote('psi'), unicode('psi'), 'psi' LIKE '%a_', 'psi' GLOB 'a*', char(85, 545), 'psi' || 'it''s', 'psi' < 'it''s', 'psi' = 'it''s' COLLATE NOCASE;
SELECT length(''), upper(''), lower(''), substr('', 0, 5), instr('', 'kappa'), replace('', 'a', '_'), trim(''), ltrim('', 'ab'), hex(''), quote(''), unicode(''), '' LIKE '%é%', '' GLOB 'a*', char(76, 824), '' || 'kappa', '' < 'kappa', '' = 'kappa' COLLATE NOCASE;
SELECT length('eta'), upper('eta'), lower('eta'), substr('eta', -1, 5), instr('eta', 'alpha'), replace('eta', 'é', '_'), trim('eta'), ltrim('eta', 'ab'), hex('eta'), quote('eta'), unicode('eta'), 'eta' LIKE 'a%', 'eta' GLOB 'a*', char(89, 647), 'eta' || 'alpha', 'eta' < 'alpha', 'eta' = 'alpha' COLLATE NOCASE;
SELECT id, (SELECT count(*) FROM t1 WHERE t1.id <= t0.id) FROM t0 ORDER BY c1, id;
SELECT id FROM t0 WHERE id IN (SELECT id FROM t1 WHERE -752.2631) ORDER BY id;
SELECT id FROM t0 x WHERE NOT EXISTS (SELECT 1 FROM t1 y WHERE y.id = x.id + 0) ORDER BY id;
SELECT id FROM t0 INTERSECT SELECT c1 FROM t1 ORDER BY 1 LIMIT 22 OFFSET 3;
